127	function respondeoNum(name: string): number {
128	  const m = name.match(/^respondeo(?:-(\d+))?\.md$/);
129	  return m ? (m[1] ? Number(m[1]) : 1) : -1;
130	}
131	
132	// Default the debate target to the most RECENT .debate/debate-* (ids are ISO
133	// timestamps, so a lexicographic sort is chronological). Explicit --debate wins.
134	async function resolveDebateDir(explicit?: string): Promise<string> {
135	  if (explicit) return explicit;
136	  const entries = await readdir(".debate", { withFileTypes: true }).catch(() => []);
137	  const dirs = entries.filter((e) => e.isDirectory() && e.name.startsWith("debate-")).map((e) => e.name).sort();
138	  if (dirs.length === 0) {
139	    console.error("[disputatio] no .debate/debate-* directory found — run a debate first");
140	    process.exit(1);
141	  }
142	  return `.debate/${dirs.at(-1)}`;
143	}
144	
145	async function loadLatestRespondeo(dir: string): Promise<{ num: number; text: string }> {
146	  const names = (await readdir(dir).catch(() => [])).filter((n) => respondeoNum(n) > 0);
147	  if (names.length === 0) {
148	    console.error(`[disputatio] no respondeo found in ${dir} — was this debate run with a judge?`);
149	    process.exit(1);
150	  }
151	  const latest = names.sort((a, b) => respondeoNum(a) - respondeoNum(b)).at(-1)!;
152	  return { num: respondeoNum(latest), text: await readFile(`${dir}/${latest}`, "utf8") };
153	}
154	
155	// Recover the quaestio from a saved transcript. debate.ts writes the header as
156	// `## Task\n\n<task>` and then appends the proposals, so the quaestio runs up to the
157	// FIRST `## Proposal — `. We can't stop at the next `## ` — the task itself routinely
158	// contains `## CONTEXT` / `## TODO` subsections (that truncated it to the title alone).
159	function extractTask(debateMd: string): string {
160	  const m = debateMd.match(/## Task\n\n([\s\S]*?)\n## Proposal — /);
161	  return m ? m[1].trim() : "(quaestio not found in transcript)";
162	}
163	
164	// --init: probe the lineup, resolve each CLI's real binary, write the user config.
165	// Branch BEFORE resolving the runtime config: init REGENERATES the user config, so its
166	// basis is an explicit --config or the built-in defaults — it must NEVER read (and choke
167	// on) the existing ~/.config/disputatio/config.yaml. Parsing its own basis here is what
168	// lets `disputatio --init --force` recover from a user config the user broke by hand.
169	// With --config the judge carries through; with no config the default opus judge is
170	// seeded (so a set-up install gets the full scholastic protocol).
171	if (initMode) {
172	  const basis: DebateConfig = configPath ? parseDebateConfig(await readFile(configPath, "utf8")) : {};
173	  const initSpecs = basis.participants ?? DEFAULT_SPECS;
174	  const initJudge = configPath ? basis.judge : DEFAULT_JUDGE;
175	  console.error(`[disputatio] init — probing: ${initSpecs.map((s) => s.adapter).join(", ")}`);
176	  const res = await runInit(initSpecs, initJudge, userConfigPath(), { force, deps: { buildParticipant } });
177	  console.error(res.report);
178	  process.exit(res.exitCode);
179	}
180	
181	// Config resolution (see install.ts): --config → ~/.config/disputatio/config.yaml →
182	// built-in lineup. The shipped examples/debate.yaml is a TEMPLATE, never auto-loaded —
183	// that coupling was the P2 footgun (its host-specific bin: broke other machines).
184	const { text: cfgText, source: cfgSource } = await resolveConfigText(configPath);
185	const cfg: DebateConfig = cfgText !== null ? parseDebateConfig(cfgText) : {};
186	
187	const specs: ParticipantSpec[] = cfg.participants ?? DEFAULT_SPECS;
188	const timeoutMs = (cfg.timeoutMinutes ?? 10) * 60_000;
189	
190	// --doctor: preflight only — needs the lineup (+ optional --config), nothing else.
191	// Branch BEFORE the task-file/rounds/repo logic so `--doctor` never gets mistaken
192	// for a task file. Short canary timeout: a hung preflight is a broken preflight.
193	// The judge is an agent that must be runnable + authenticated like any other — canary it too.
194	if (doctorMode) {
195	  console.error(`[disputatio] config: ${cfgSource}`);
196	  const participants = specs.map((s) => buildParticipant(s, CANARY_TIMEOUT_MS));
197	  if (cfg.judge) participants.push(buildParticipant(cfg.judge, CANARY_TIMEOUT_MS));
198	  console.error(`[disputatio] doctor — canary: ${participants.map((p) => p.id).join(", ")}`);
199	  const diagnoses = await runDoctor(participants);
200	  console.error(formatDiagnoses(diagnoses));
201	  process.exit(allHealthy(diagnoses) ? 0 : 1);
202	}
203	
204	// --continue / --finalize close the human-in-the-loop: they re-enter an EXISTING debate
205	// on disk (no new debate runs). Both need the judge/synthesizer — fall back to the
206	// built-in opus judge when the config has none (the default lineup is judge-less, but
207	// closing the loop is intrinsically a judge act). Branch BEFORE quaestio resolution:
208	// the quaestio is recovered from the saved transcript, not the CLI.
209	if (continueArg !== undefined || finalizeMode) {
210	  const dir = await resolveDebateDir(debateArg);
211	  const { num, text: prevDetermination } = await loadLatestRespondeo(dir);
212	  const transcript = await readFile(`${dir}/debate.md`, "utf8");
213	  const quaestio = extractTask(transcript);
214	  const judge = buildParticipant(withBudget(cfg.judge ?? DEFAULT_JUDGE), timeoutMs);
215	  console.error(`[disputatio] config: ${cfgSource}`);
216	
217	  // --repo grounds ONLY the redactio (the deliverable), in a read-only worktree of HEAD.
218	  // The re-judge stays transcript-only (respondeo invariant: it trusts the human's answers,
219	  // it does not re-litigate against the repo). So --repo is meaningful here only because a
220	  // RESOLVED continuation, and every --finalize, ends in a redactio. Validate it's git.
221	  const finalizeRepo = repoArg ?? cfg.repo;
222	  if (finalizeRepo) {
223	    try {
224	      await execFileAsync("git", ["-C", finalizeRepo, "rev-parse", "--is-inside-work-tree"]);
225	    } catch {
226	      console.error(`[disputatio] ${finalizeRepo} is not a git repository — redactio evidence mode requires git (read-only worktree of HEAD)`);
227	      process.exit(1);
228	    }
229	    console.error(`[disputatio] redactio will ground the deliverable in ${finalizeRepo} (read-only worktree of HEAD)`);
230	  }
231	
232	  // --finalize: (re)draft the deliverable from a determination that ALREADY resolved.
233	  // Refuse on NEEDS_INPUT — there is no settled verdict to synthesize yet; --continue first.
234	  if (finalizeMode) {
235	    if (parseRespondeoStatus(prevDetermination) === "NEEDS_INPUT") {
236	      console.error(`[disputatio] respondeo #${num} in ${dir} still needs input — run --continue "<answers>" first`);
237	      process.exit(1);
238	    }
239	    console.error(`[disputatio] finalize — drafting deliverable for ${dir} with ${judge.display}`);
240	    const fin = await runFinalize(judge, quaestio, transcript, prevDetermination, finalizeRepo);
241	    await writeFile(`${dir}/raw/finalize-respondeo.json`, JSON.stringify(fin, null, 2), "utf8");
242	    if (!fin.result.ok) {
243	      const hint = fin.result.budgetExhausted
244	        ? `\n[disputatio]    retry: disputatio --finalize --budget <usd> --debate ${dir}${finalizeRepo ? ` --repo ${finalizeRepo}` : ""}`
245	        : "";
246	      console.error(`[disputatio] finalize FAILED: ${fin.result.error}${hint}`);
247	      process.exit(1);
248	    }
249	    await writeFile(`${dir}/final-report.md`, fin.result.text, "utf8");
250	    console.error(`[disputatio] final report: ${dir}/final-report.md`);
251	    console.log(`${dir}/final-report.md`);
252	    process.exit(0);
253	  }
254	
255	  // --continue: the human answered the open questions → re-judge (judge-only path).
256	  console.error(`[disputatio] continue — re-judging ${dir} (from respondeo #${num}) with ${judge.display}`);
257	  const turn = await runContinuation(judge, quaestio, transcript, prevDetermination, continueArg!);
258	  const nextNum = num + 1;
259	  await writeFile(`${dir}/raw/continue-${nextNum}-input.txt`, continueArg!, "utf8");
260	  await writeFile(`${dir}/raw/continue-${nextNum}-respondeo.json`, JSON.stringify(turn, null, 2), "utf8");
261	  if (!turn.result.ok) {
262	    console.error(`[disputatio] continuation FAILED: ${turn.result.error}`);
263	    process.exit(1);
264	  }
265	  const status = parseRespondeoStatus(turn.result.text);
266	  const respPath = `${dir}/respondeo-${nextNum}.md`;
267	  await writeFile(respPath, turn.result.text, "utf8");
268	  console.error(`[disputatio] respondeo (${status}): ${respPath}`);
269	
270	  if (status === "NEEDS_INPUT") {
271	    // The answer opened ground the debaters never argued — the judge refused to invent a
272	    // verdict. Answer again with --continue, or re-run the debate to re-engage the debaters.
273	    console.error(`[disputatio] ⚠️ still needs input — your answer opened a point the debaters never argued; answer again with --continue, or re-run the debate to re-engage them`);
274	    console.log(respPath);
275	    process.exit(0);
276	  }
277	
278	  // RESOLVED → author the deliverable (final-report.md is overwritten: it is the CURRENT deliverable).
279	  const fin = await runFinalize(judge, quaestio, transcript, turn.result.text, finalizeRepo);
280	  await writeFile(`${dir}/raw/continue-${nextNum}-final-report.json`, JSON.stringify(fin, null, 2), "utf8");
281	  if (fin.result.ok) {
282	    await writeFile(`${dir}/final-report.md`, fin.result.text, "utf8");
283	    console.error(`[disputatio] final report: ${dir}/final-report.md`);
284	    console.log(`${dir}/final-report.md`);
285	  } else {
286	    const hint = fin.result.budgetExhausted
287	      ? `\n[disputatio]    retry: disputatio --finalize --budget <usd> --debate ${dir}${finalizeRepo ? ` --repo ${finalizeRepo}` : ""}`
288	      : "";
289	    console.error(`[disputatio] ⚠️ finalize failed: ${fin.result.error}${hint}`);
290	    console.log(respPath);
291	  }
292	  process.exit(0);
293	}
294	
295	// Quaestio: inline by default (the sole positional), or read from --file <path>.
296	const input = resolveQuaestioInput(filePath, positionals);
297	if (!input.ok) {
298	  console.error(`[disputatio] ${input.error}`);
299	  usage(1);
300	}
301	let task: string;
302	if (input.source === "file") {
303	  task = await readFile(input.path, "utf8");
304	  console.error(`[disputatio] quaestio: ${input.path}`);
305	} else {
306	  task = input.text;
307	  console.error(`[disputatio] quaestio: inline (${input.text.length} chars)`);
308	}
309	
310	const rounds = roundsArg !== undefined ? Number(roundsArg) : cfg.rounds ?? 1;
311	if (!Number.isInteger(rounds) || rounds < 0) {
312	  console.error(`[disputatio] rounds must be a non-negative integer, got "${roundsArg}"`);
313	  process.exit(1);
314	}
315	const repoPath = repoArg ?? cfg.repo;
316	
317	// READ-ONLY invariant: evidence gathering happens in a throwaway git worktree,
318	// never in the real checkout — so the repo must be a git repo. Fail fast here.
319	if (repoPath) {
320	  try {
321	    await execFileAsync("git", ["-C", repoPath, "rev-parse", "--is-inside-work-tree"]);
322	  } catch {
323	    console.error(`[disputatio] ${repoPath} is not a git repository — evidence mode requires git (agents run in a throwaway worktree)`);
324	    process.exit(1);
325	  }
326	  const { stdout } = await execFileAsync("git", ["-C", repoPath, "status", "--porcelain"]);
327	  if (stdout.trim() !== "") {
328	    console.error(`[disputatio] ⚠️ ${repoPath} has uncommitted changes — agents see HEAD only, not your working tree`);
329	  }
330	}
331	
332	console.error(`[disputatio] config: ${cfgSource}`);
333	const participants = specs.map((s) => buildParticipant(s, timeoutMs));
334	
335	const vendors = new Set(participants.map((p) => p.vendor));
336	if (vendors.size < participants.length) {
337	  console.error("[disputatio] ⚠️ participants are not all cross-vendor — correlated-error risk (docs/2_CONCEPT.md §2)");
338	}
339	
340	const judge = cfg.judge ? buildParticipant(withBudget(cfg.judge), timeoutMs) : undefined;
341	
342	// Correlated-error guard for the judge. display encodes adapter+model, so an exact
343	// match means a debater is grading its OWN argument (same vendor AND model) — the loud
344	// ⚠️. A shared vendor (different model) is a milder shared-training-lineage risk — a note.
345	if (judge) {
346	  if (participants.some((p) => p.display === judge.display)) {
347	    console.error(`[disputatio] ⚠️ judge ${judge.display} is identical to a debater — it would grade its own argument (correlated-error risk; docs/2_CONCEPT.md §2)`);
348	  } else if (participants.some((p) => p.vendor === judge.vendor)) {
349	    console.error(`[disputatio] note: judge ${judge.display} shares a vendor with a debater — mild shared-training-lineage risk`);
350	  }
351	}
352	
353	const outcome = await runDebate(task, participants, rounds, repoPath, judge);
354	
355	const id = `debate-${new Date().toISOString().replace(/[:.]/g, "-")}`;
356	const dir = `.debate/${id}`;
357	await mkdir(`${dir}/raw`, { recursive: true });
358	await writeFile(`${dir}/debate.md`, outcome.transcript, "utf8");
359	
360	// Per-turn raw CLI captures: when a turn FAILS, the envelope/stderr here is the
361	// only way to diagnose it (lesson from debate-2026-06-11: "is_error=true" with
362	// everything else discarded was undiagnosable).
363	for (let i = 0; i < outcome.turns.length; i++) {
364	  const t = outcome.turns[i];
365	  const slug = t.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60);
366	  await writeFile(`${dir}/raw/${String(i + 1).padStart(2, "0")}-${slug}.json`, JSON.stringify(t, null, 2), "utf8");
367	}
368	
369	if (outcome.aborted) {
370	  console.error(`[disputatio] debate ABORTED: ${outcome.aborted}`);
371	  console.error(`[disputatio] partial transcript + raw captures kept for diagnosis`);
372	  console.log(`${dir}/debate.md`); // still expose the artifact path for inspection
373	  process.exit(1);
374	}
375	
376	// Respondeo (consolidatio) artifact, alongside debate.md. NEEDS_INPUT is not an abort:
377	// the judge did its job by asking instead of guessing — surface it on stderr, exit 0.
378	if (outcome.respondeo) {
379	  await writeFile(`${dir}/respondeo.md`, outcome.respondeo.text, "utf8");
380	  console.error(`[disputatio] respondeo (${outcome.respondeo.status}): ${dir}/respondeo.md`);
381	  if (outcome.respondeo.status === "NEEDS_INPUT") {
382	    console.error(`[disputatio] ⚠️ respondeo needs human input — see ${dir}/respondeo.md`);
383	    console.error(`[disputatio]    answer it to close the loop: disputatio --continue "<answers>"`);
384	  }
385	}
386	
387	// Redactio (the deliverable) artifact, only when the respondeo RESOLVED. This is what
388	// you actually start the work from — distinct from respondeo.md, which rules ON the debate.
389	if (outcome.finalReport) {
390	  await writeFile(`${dir}/final-report.md`, outcome.finalReport.text, "utf8");
391	  console.error(`[disputatio] final report: ${dir}/final-report.md`);
392	} else if (outcome.finalReportError) {
393	  const hint = outcome.finalReportError.budgetExhausted
394	    ? `\n[disputatio]    retry: disputatio --finalize --budget <usd> --debate ${dir}${repoPath ? ` --repo ${repoPath}` : ""}`
395	    : "";
396	  console.error(`[disputatio] ⚠️ redactio failed: ${outcome.finalReportError.message}${hint}`);
397	}
398	
399	console.error(`[disputatio] done`);
400	// stdout = the PRIMARY artifact (agent-native friendly). When a deliverable was produced
401	// it IS the actionable artifact, so point downstream consumers at it; otherwise the
402	// transcript is all there is.
403	console.log(outcome.finalReport ? `${dir}/final-report.md` : `${dir}/debate.md`);

